head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.vScrenTpCD = "";
scwin.vBzProcsNo = "";
scwin.vIsurCd = "";
scwin.vAcptNo = "";
// showObj(ObjID, flag) SetWindowPos(ObjID, nTop, nLeft, nWidth, nHeight)
// 세션정보를 얻기위한 함수사용

scwin.trsIdx; // insert, update 구분
scwin.rowPos;
scwin.fr_SecuGrpId = SECUGRP_ID_BC;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.libRoundPanel.PanelToGroupBox(panel_Top);
        $c.libRoundPanel.PanelToGroupBox(panel_Item);

        /* buttonSet의 초기화를 수행한다.  각 용도에 맞게 이미지ID와 onclick event시 수행할 function을 지정한다. */
        buttonSet.setSaveInfo(btn_Save, scwin.save); // 저장
        buttonSet.setUpdateInfo(btn_Update, scwin.update); // 수정
        buttonSet.setDeleteInfo(btn_Delete, scwin.delete); // 삭제
        buttonSet.setDsclInfo(btn_Dscl, scwin.dscl); // 안내문작성
        buttonSet.setDrftInfo(btn_Drft, scwin.drft); // 기안

        buttonSet.setInsertStatus();
        const sbmOptions = {
            id : "sbm_dts_Isu",
            action : "/gauceSystemierAdaptor.do",
            ref : "",
            target : "dts_Isu=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        await scwin.recvListSync();
        buttonSet.setButtonSecugrpDepCd(dts_ByCorpDepCd, scwin.fr_SecuGrpId, scwin.vIsurCd, js_dep_cd);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05410.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
// function fn_makt() { }

/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    try {
        if (txb_ISU_CD.getValue() === "") {
            await $c.win.alert("[종목]을 선택하세요.");
            txb_ISU_CD.focus();
            return;
        } else {
            scwin.initItem();
            await scwin.isubookReadSync();
            await scwin.allListSync();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05410.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name btn_RecvIsuDel_onclick
 * @description 「신청종목삭제」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_RecvIsuDel_onclick = async function() {
    try {
        await scwin.recvtIsuDel();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05410.btn_RecvIsuDel_onclick" });
