/**
 * @method
 * @name dts_Recv_OnLoadCompleted
 * @description dts_Recv 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_Recv_OnLoadCompleted = function(rowcount) {
    try {
        edt_TotalCnt_1.setValue("총 " + dts_Recv.getRowCount() + " 건");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05410.dts_Recv_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_Mst_OnLoadCompleted
 * @description dts_Mst 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_Mst_OnLoadCompleted = function(rowcount) {
    try {
        if (scwin.vBzProcsNo === "") {
            buttonSet.setInsertStatus();
        } else {
            if ($c.ut.cGetToday("yyyymmdd") <= edt_DELIST_DD.getValue()) {
                buttonSet.setUpdateStatus();
            } else {
                buttonSet.setErrorStatus();
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05410.dts_Mst_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadCompleted
 * @description dts_List 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    try {
        $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page);
        if (scwin.vBzProcsNo === "") {
            buttonSet.setInsertStatus();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05410.dts_List_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name trs_Save_OnSuccess
 * @description Save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnSuccess = async function() {
    try {
        $c.lc.fn_alertMsg('S');
        await scwin.allListSync();
        scwin.initItem();
        if (buttonSet.status !== "D") {
            // 삭제처리의 응답인 경우
            await scwin.readSync(dts_List.getRowCount());
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05410.trs_Save_OnSuccess" });
    }
};

/**
 * @method
 * @name trs_Save_OnFail
 * @description Save On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnFail = async function() {
    try {
        $c.lc.fn_alertMsg('F');
        await $c.win.alert(trs_Save);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05410.trs_Save_OnFail" });
    }
};

/**
 * @method
