/**
 * @method
 * @name openSchdlDetail
 * @description open Schdl Detail 처리
 * @param {Number} row 행 인덱스
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.openSchdlDetail = async function(row) {
    buttonSet.setInsertStatus();
    scwin.initItem();
    const r = dts_Recv.getRowPosition();
    scwin.vIsurCd = dts_Recv.getCellData(r, "ISUR_CD");
    txb_ISU_CD.setValue(dts_Recv.getCellData(r, "ISU_CD"));
    txb_ISU_NM.setValue(dts_Recv.getCellData(r, "ISU_KOR_NM"));
    await scwin.isubookReadSync();
    await scwin.listSync();
    scwin.vBzProcsNo = dts_Recv.getCellData(r, "BZ_PROCS_NO");
    scwin.vAcptNo = dts_Recv.getCellData(r, "ACPT_NO");
    // alert('[vAcptNo]'+vAcptNo);
    dts_Mst.setCellData(1, "BZ_PROCS_NO", dts_Recv.getCellData(r, "BZ_PROCS_NO"));
    dts_Mst.setCellData(1, "DELIST_DD", dts_Recv.getCellData(r, "TERMNT_DD"));
    dts_Mst.setCellData(1, "REMK", dts_Recv.getCellData(r, "REMK"));
};

/**
 * @method
 * @name initItem
 * @description init Item 처리
 * @returns {void}
 * @hidden N
 */
scwin.initItem = function() {
    buttonSet.setInsertStatus();
    dts_Isu.removeAll();
    dts_Isu.insertRow();
    dts_Mst.removeAll();
    dts_Mst.insertRow();
    scwin.vBzProcsNo = ""; // 초기화
    scwin.vAcptNo = "";
};

/**
 * @method
 * @name checkForm
 * @description check Form 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkForm = async function() {
    const vCurDate = $c.ut.cGetToday("yyyymmdd");
    if (txb_ISU_CD.getValue() === "") {
        await $c.win.alert("[종목코드]를 선택하세요.");
        txb_ISU_CD.focus();
        return false;
    }
    if (edt_DELIST_DD.getValue() === "") {
        await $c.win.alert("[상장폐지일]을 입력하세요.");
        edt_DELIST_DD.focus();
        return false;
    }
    if ($c.ut.cGetToday("yyyymmdd") >= edt_DELIST_DD.getValue()) {
        await $c.win.alert("[상장폐지일]을 현재일이후로 입력하세요.");
        edt_DELIST_DD.focus();
        return false;
    }
    if (dts_Mst.getCellData(1, "DELIST_RSN_CD") === "") {
        await $c.win.alert("[상장폐지사유]를 선택하세요.");
        txb_DELIST_RSN_DSC.focus();
        return false;
    }
    if (txb_GRND_REGUL_NM.getValue() === "") {
        await $c.win.alert("[근거규정]을 입력하세요.");
        txb_GRND_REGUL_NM.focus();
        return false;
    }
    if (!$c.stf.checkMaxLength(txb_GRND_REGUL_NM, 200, "근거규정")) return false;
    return true;
};

/**
 * @method
 * @name save
 * @description save 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function() {
    scwin.trsIdx = TRS_IDX_INSERT;
    if (!await scwin.checkForm()) return;
    if (!$c.lc.fn_isProcess('I')) return;
    if (scwin.vAcptNo === "") {
        scwin.vBzProcsNo = await $c.stf.getNewBzProcNo(dts_BzProcsNo);
    }
    if (scwin.vBzProcsNo.length !== 14) {
        await $c.win.alert($c.stf.getMessageParam("MSG-0010", ""));
    } else {
        dts_Mst.setCellData(1, "BZ_PROCS_NO", scwin.vBzProcsNo);
        // alert('[dts_Mst]'+dts_Mst.text);
        await scwin.trs();
    }
};

/**
 * @method
 * @name update
 * @description update 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.update = async function() {
    scwin.trsIdx = TRS_IDX_UPDATE;
    if (!await scwin.checkForm()) return;
    if (!$c.lc.fn_isProcess('U')) return;
    await scwin.trs();
};

/**
 * @method
 * @name delete
 * @description delete 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.delete = async function() {
    if (!$c.lc.fn_isProcess('D')) return;
    buttonSet.setDeleteStatus(); // buttonSet에 CRUD상태를 저장하여 이용하는 사례, TR의 응답event에서 사용.
    scwin.vAcptNo = "";
    scwin.trsIdx = TRS_IDX_DELETE;
    await scwin.trs();
};

/**
 * @method
 * @name recvtIsuDel
 * @description recvt Isu Del 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.recvtIsuDel = async function() {
    if (scwin.vAcptNo === "") {
        await $c.win.alert('상장폐지예정내역에서 대상종목을 선택하세요');
        return;
    }
    await scwin.delete();
};

